<script setup>
import {computed,onUnmounted,ref} from 'vue'
import {LayoutDashboard,LogOut,RefreshCw,ShieldCheck,Activity,Settings,ClipboardList,CheckCircle2} from 'lucide-vue-next'
import {request} from './api'
import {modules,statuses,formatDate,money} from './campus-catalog'
import IdleSession from './components/IdleSession.vue'
import './payments.css'
import './kiosk.css'
import './campus.css'
const password=ref(''),token=ref(''),data=ref(null),tab=ref('operations'),filter=ref('active'),kind=ref('all'),busy=ref(false),error=ref(''),notice=ref(''),edit=ref(null),draft=ref(null),selected=ref(null),note=ref(''),confirm=ref(null)
let controller=new AbortController(),expiry,poll
const rows=computed(()=>data.value?.records.filter(r=>(kind.value==='all'||r.kind===kind.value)&&(filter.value==='all'||!['cancelado','entregado','completado','rechazado'].includes(r.status)))||[])
const reportModules=[...modules,{id:'charges',title:'Pagos'},{id:'history',title:'Comprobantes'},{id:'billing',title:'Facturación'},{id:'parking',title:'Estacionamiento'},{id:'system',title:'Conectividad del kiosco'}]
const pending=computed(()=>data.value?.records.filter(r=>['recibido','revision','espera','llamado','reservado','listo'].includes(r.status)).length||0)
const unresolved=computed(()=>data.value?.incidents.filter(i=>!i.resolved).length||0)
const mapping={procedure:{recibido:['revision','rechazado'],revision:['listo','rechazado'],listo:['entregado']},turn:{espera:['llamado','cancelado'],llamado:['completado']},appointment:{reservado:['completado','cancelado']},book:{reservado:['entregado','cancelado']},activity:{inscrito:['completado','cancelado']}}
function recordName(r){return data.value?.config.departments.find(d=>d.id===r.item)?.name||data.value?.config.activities.find(a=>a.id===r.item)?.name||{estudios:'Constancia de estudios',calificaciones:'Constancia de calificaciones',credencial:'Reposición de credencial',reinscripcion:'Reinscripción',algebra:'Álgebra',historia:'Historia de México',programacion:'Programación'}[r.item]||r.item}
async function refresh(){const signal=controller.signal;const response=await request('/admin/state',{token:token.value,signal});if(!signal.aborted)data.value=response}
async function login(){
 if(busy.value)return
 busy.value=true;error.value='';const signal=controller.signal
 try{const r=await request('/admin/login',{method:'POST',body:{password:password.value},signal});if(signal.aborted)return;token.value=r.access_token;password.value='';await refresh();if(signal.aborted)return;expiry=setTimeout(logout,r.expires_in*1000);poll=setInterval(()=>{if(!busy.value&&!edit.value&&!confirm.value)refresh().catch(handle)},15000)}catch(e){if(!signal.aborted)handle(e)}finally{if(!signal.aborted)busy.value=false}
}
function handle(e){if(controller.signal.aborted||e.name==='AbortError')return;if(e.status===403&&token.value){logout();error.value='La sesión administrativa venció.'}else error.value=e.message}
function logout(){const old=token.value;controller.abort();controller=new AbortController();token.value='';password.value='';data.value=null;edit.value=null;confirm.value=null;selected.value=null;draft.value=null;note.value='';notice.value='';error.value='';busy.value=false;clearTimeout(expiry);clearInterval(poll);if(old)request('/auth/logout',{method:'POST',token:old}).catch(()=>{})}
async function perform(payload){
 if(busy.value)return
 busy.value=true;error.value='';notice.value='';const signal=controller.signal
 try{await request('/admin/action',{method:'POST',token:token.value,body:payload,signal});if(signal.aborted)return;await refresh();if(signal.aborted)return;edit.value=null;confirm.value=null;selected.value=null;note.value='';notice.value='Cambios guardados. El kiosco los verá al actualizar.'}catch(e){if(!signal.aborted)handle(e)}finally{if(!signal.aborted)busy.value=false}
}
function configure(section){edit.value=section;draft.value=JSON.parse(JSON.stringify(data.value.config[section]));error.value=''}
function change(r,status){selected.value=r;note.value='';confirm.value={action:'transition',folio:r.folio,status}}
onUnmounted(()=>{controller.abort();clearInterval(poll);clearTimeout(expiry)})
</script>
<template><div class="admin-app"><IdleSession :active="!!token" extended @expired="logout"/><header class="admin-header"><a href="/" class="admin-brand"><img src="/images/logo.jpg" alt="Justo Sierra"><div><b>Campus · Administración</b><small>ENTORNO DE DEMOSTRACIÓN</small></div></a><button v-if="token" class="btn-outline" @click="logout"><LogOut :size="18"/> Cerrar sesión</button></header>
 <main v-if="!token" class="admin-login campus-panel"><ShieldCheck :size="42"/><h1>Acceso del personal</h1><p>Gestiona solicitudes, atención y servicios desde la computadora del operador.</p><form @submit.prevent="login"><label>Contraseña administrativa<input v-model="password" type="password" autocomplete="current-password" maxlength="256" required></label><p class="flow-error" v-if="error" role="alert">{{error}}</p><button class="btn-primary full" :disabled="busy">{{busy?'VALIDANDO…':'INGRESAR A ADMINISTRACIÓN'}}</button></form><p class="admin-setup">Primera vez: ejecuta <code>python api/setup_admin.py</code> y reinicia la API. No se utiliza el PIN de alumnos.</p></main>
 <div v-else class="admin-layout"><aside class="admin-sidebar"><button v-for="[id,label,icon] in [['operations','Atención y trámites',ClipboardList],['students','Validaciones y biblioteca',ShieldCheck],['settings','Servicios y avisos',Settings],['monitor','Estado del sistema',Activity],['reports','Reportes de uso',LayoutDashboard]]" :key="id" :aria-current="tab===id?'page':undefined" @click="tab=id;edit=null;notice=''"><component :is="icon" :size="20"/>{{label}}</button><p>Los registros son ficticios. Las acciones de este panel modifican la base demo compartida con el kiosco.</p></aside><main class="admin-content"><div class="campus-heading"><div><span class="eyebrow red">CONTROL DEL CAMPUS</span><h1>{{{operations:'Atención y trámites',students:'Validaciones y biblioteca',settings:'Servicios y avisos',monitor:'Estado del sistema',reports:'Reportes de uso'}[tab]}}</h1></div><button class="btn-outline" :disabled="busy" @click="refresh().catch(handle)"><RefreshCw :size="18"/> Actualizar</button></div><p v-if="error" class="flow-error" role="alert">{{error}}</p><p v-if="notice" class="campus-success" role="status">{{notice}}</p><template v-if="data">
 <div class="admin-stats"><div><small>PENDIENTES DE ATENCIÓN</small><strong>{{pending}}</strong></div><div><small>INCIDENTES ABIERTOS</small><strong>{{unresolved}}</strong></div><div><small>EXPERIENCIA PROMEDIO</small><strong>{{data.surveys.average||'—'}} <small>/ 5</small></strong></div></div>
 <template v-if="tab==='operations'"><div class="admin-filters"><label>Servicio<select v-model="kind"><option value="all">Todos</option><option value="procedure">Trámites</option><option value="turn">Turnos</option><option value="appointment">Citas</option><option value="book">Reservas de libros</option><option value="activity">Actividades</option></select></label><label>Estado<select v-model="filter"><option value="active">Activos</option><option value="all">Todos</option></select></label></div><p>Turnos: llama primero al más antiguo de cada área. Las citas muestran la hora local del kiosco.</p><div v-if="!rows.length" class="campus-empty">No hay registros para este filtro.</div><article class="campus-record" v-for="r in rows" :key="r.id"><div><span class="campus-folio">{{r.folio}} · {{r.matricula}}</span><h3>{{recordName(r)}}</h3><p>{{r.kind==='appointment'?formatDate(r.detail):formatDate(r.created)}}</p><p v-if="r.fee">{{money(r.fee)}} · {{r.paid?'Pagado demo':'Pago pendiente'}}</p><small>{{r.history.at(-1)?.note}}</small></div><div class="record-actions"><span class="campus-status">{{statuses[r.status]}}</span><button v-for="status in mapping[r.kind]?.[r.status]||[]" :key="status" class="btn-outline" :disabled="busy" @click="change(r,status)">{{statuses[status]}}</button></div></article><p class="delivery-note">Se muestran los 300 registros más recientes. El historial completo permanece en la base local.</p></template>
 <template v-else-if="tab==='students'"><section class="campus-panel"><h2>Validaciones de reinscripción</h2><p>Marca solamente lo revisado en esta demostración. Los alumnos aparecen después de abrir Servicios del campus.</p><div class="validation-row" v-for="v in data.validations" :key="v.matricula"><b>{{v.matricula}}</b><label><input type="checkbox" :checked="!!v.documents" @change="v.documents=$event.target.checked"> Documentación revisada</label><label><input type="checkbox" :checked="!!v.academic" @change="v.academic=$event.target.checked"> Validación académica</label><button class="btn-outline" :disabled="busy" @click="perform({action:'validate',matricula:v.matricula,documents:!!v.documents,academic:!!v.academic})">Guardar validaciones</button></div></section><section class="campus-panel"><h2>Préstamos activos</h2><div class="loan-row" v-for="l in data.loans" :key="l.id"><div><b>{{l.matricula}} · {{recordName({item:l.book})}}</b><p>Vence {{formatDate(l.due)}}</p></div><button class="btn-outline" :disabled="busy" @click="confirm={action:'return_book',id:l.id};selected=null">Registrar devolución</button></div><p v-if="!data.loans.length">No hay préstamos activos.</p></section></template>
 <template v-else-if="tab==='settings'"><div v-if="!edit" class="campus-grid two"><article v-for="[section,title,description] in [['announcements','Avisos del campus','Hasta cinco mensajes públicos.'],['disabled','Disponibilidad de servicios','Suspende nuevas solicitudes conservando los registros.'],['departments','Directorio y horarios','Actualiza ubicaciones, horarios y requisitos.'],['activities','Talleres y cupos','Gestiona horarios, lugares e inscripciones.'],['procedures','Trámites y costos','Configura plazos, requisitos y costos de solicitudes nuevas.']]" :key="section" class="campus-panel"><h2>{{title}}</h2><p>{{description}}</p><button class="btn-outline" @click="configure(section)">Editar {{title.toLowerCase()}}</button></article></div><form v-else class="campus-panel admin-editor" @submit.prevent="perform({action:'config',section:edit,value:draft})"><h2>Editar configuración</h2><template v-if="edit==='announcements'"><div v-for="(a,i) in draft" :key="i" class="admin-edit-row"><label>Título<input v-model="a.title" maxlength="80" required></label><label>Mensaje<textarea v-model="a.text" maxlength="240" required></textarea></label><button type="button" class="campus-cancel" @click="draft.splice(i,1)">Quitar aviso</button></div><button type="button" class="btn-outline" :disabled="draft.length>=5" @click="draft.push({title:'',text:''})">Agregar aviso</button></template><template v-else-if="edit==='disabled'"><p>Marca los servicios que estarán temporalmente fuera de atención.</p><label class="admin-check" v-for="m in modules" :key="m.id"><input type="checkbox" v-model="draft" :value="m.id">{{m.title}}</label></template><template v-else-if="edit==='departments'"><div class="admin-edit-row" v-for="d in draft" :key="d.id"><h3>{{d.id}}</h3><label>Primera cita (hora, 7 a 19)<input v-model.number="d.start_hour" type="number" min="7" max="19" required></label><label>Cierre de citas (hora, 8 a 20)<input v-model.number="d.end_hour" type="number" min="8" max="20" required></label><label v-for="[key,label] in [['name','Nombre'],['location','Ubicación'],['hours','Horario de atención'],['requirements','Requisitos'],['contact','Contacto']]" :key="key">{{label}}<input v-model="d[key]" maxlength="160" required></label></div><p>Las citas ofrecen bloques de una hora, lunes a viernes, dentro del intervalo configurado. Los cambios afectan nuevos horarios; las reservas existentes se conservan.</p></template><template v-else-if="edit==='procedures'"><div class="admin-edit-row" v-for="p in draft" :key="p.id"><label>Nombre<input v-model="p.name" maxlength="80" required></label><label>Requisitos<textarea v-model="p.requirements" maxlength="240" required></textarea></label><label>Costo demo MXN<input v-model.number="p.fee" type="number" min="0" max="10000" step="0.01" :disabled="p.id==='reinscripcion'" required></label><label>Plazo de referencia (días hábiles)<input v-model.number="p.days" type="number" min="1" max="30" required></label></div><p>Los costos de solicitudes existentes se conservan.</p></template><template v-else><div class="admin-edit-row" v-for="a in draft" :key="a.id"><label v-for="[key,label] in [['name','Nombre'],['schedule','Horario'],['location','Lugar']]" :key="key">{{label}}<input v-model="a[key]" maxlength="120" required></label><label>Cupo<input v-model.number="a.capacity" type="number" min="1" max="100" required></label><label class="admin-check"><input type="checkbox" v-model="a.enabled"> Inscripciones abiertas</label></div></template><div class="campus-actions"><button type="button" class="btn-outline" :disabled="busy" @click="edit=null">Cancelar edición</button><button class="btn-primary" :disabled="busy">Guardar configuración</button></div></form></template>
 <template v-else-if="tab==='monitor'"><div class="campus-grid two"><article class="campus-panel"><h2>API y almacenamiento</h2><p class="campus-success"><CheckCircle2 :size="20"/> Conectados · base consultada correctamente</p><p>Los cortes de API se registran al recuperar conexión del kiosco. Si esta pantalla no logra actualizar, se muestra el error de conexión.</p></article><article class="campus-panel"><h2>Entrega por correo</h2><p>{{data.email_available?'SMTP configurado. La entrega se confirma por cada operación.':'Pendiente de configurar un proveedor SMTP con TLS.'}}</p><p>El estado «aceptado» indica recepción por SMTP, no lectura ni llegada a bandeja.</p></article></div><section class="campus-panel"><h2>Incidentes de impresión</h2><p v-if="!data.incidents.length">No hay fallas registradas. Esto no comprueba que la impresora esté conectada.</p><div class="loan-row" v-for="i in data.incidents" :key="i.id"><div><b>{{i.source}}</b><p>{{i.detail}}</p><small>{{formatDate(i.created)}}</small></div><button v-if="!i.resolved" class="btn-outline" :disabled="busy" @click="perform({action:'resolve',id:i.id})">Marcar revisado</button><span v-else>Revisado</span></div></section><section class="campus-panel"><h2>Envíos que requieren revisión</h2><p v-if="!data.deliveries.length">No hay envíos pendientes o con error.</p><div class="loan-row" v-for="d in data.deliveries" :key="d.request_id"><div><b>{{d.masked_recipient}}</b><p>{{d.request_id}}</p></div><span class="campus-status">{{d.status}}</span></div><p>No se reenvían automáticamente las entregas ambiguas para evitar duplicados.</p></section></template>
 <template v-else-if="tab==='reports'"><section class="campus-panel"><h2>Uso por servicio</h2><p>Sesiones anónimas. Un evento de cada tipo por servicio y sesión; «salida» indica que se dejó la pantalla, no que una transacción falló.</p><div class="report-row" v-for="m in reportModules" :key="m.id"><b>{{m.title}}</b><span v-for="[event,label] in [['open','visitas'],['complete','finalizaciones'],['abandon','salidas'],['api_offline','cortes de API']]" :key="event">{{data.metrics.find(r=>r.module===m.id&&r.event===event)?.total||0}} {{label}}</span></div></section><section class="campus-panel"><h2>Distribución de visitas por hora (UTC)</h2><p v-if="!data.hours.length">Todavía no hay visitas registradas.</p><div class="report-hour" v-for="h in data.hours" :key="h.hour"><b>{{h.hour}}:00</b><meter min="0" :max="Math.max(...data.hours.map(v=>v.total),1)" :value="h.total"></meter><span>{{h.total}}</span></div></section><section class="campus-panel"><h2>Encuestas</h2><p>{{data.surveys.total}} respuestas · promedio {{data.surveys.average||'sin respuestas'}} / 5.</p></section></template>
 </template><p v-else>Cargando administración…</p></main></div>
 <div v-if="confirm" class="kiosk-modal-backdrop"><section class="kiosk-modal" role="dialog" aria-modal="true" aria-labelledby="admin-confirm"><h2 id="admin-confirm">Confirmar actualización</h2><p v-if="selected">{{selected.folio}} → {{statuses[confirm.status]}}</p><p v-else>El préstamo se marcará como devuelto y liberará el ejemplar.</p><label v-if="selected">Nota para el alumno<input v-model="note" maxlength="240" placeholder="Motivo o instrucciones de entrega"></label><p v-if="error" class="flow-error" role="alert">{{error}}</p><div class="campus-actions"><button class="btn-outline" :disabled="busy" @click="confirm=null">Volver</button><button class="btn-primary" :disabled="busy" @click="perform({...confirm,...(selected?{note:note.trim()||'Actualizado por administración demo.'}:{})})">Confirmar cambio</button></div></section></div>
</div></template>
